struct Query {
    char t;      
    int a, b;    
    int old;     
};

struct DSU {
    vector<int> p, sz;
    vector<long long> comp_sum;
    priority_queue<pair<long long,int>> pq;

    DSU(int n, const vector<long long>& w)
      : p(n+1), sz(n+1,1), comp_sum(n+1) {
        iota(p.begin(), p.end(), 0);
        for(int i = 1; i <= n; i++){
            comp_sum[i] = w[i];
            pq.emplace(comp_sum[i], i);
        }
    }

    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }

    void unite(int u, int v) {
        u = find(u);
        v = find(v);
        if(u == v) return;
        if(sz[u] < sz[v]) swap(u, v);
        p[v] = u;
        sz[u] += sz[v];
        comp_sum[u] += comp_sum[v];
        pq.emplace(comp_sum[u], u);
    }

    void deltapply(int x, long long delta) {
        int r = find(x);
        comp_sum[r] += delta;
        pq.emplace(comp_sum[r], r);
    }

    long long max() {
        while(true) {
            auto [s, r] = pq.top();
            if(find(r) == r && comp_sum[r] == s)
                return s;
            pq.pop();
        }
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, q;
    cin >> n >> m >> q;

    vector<long long> w(n+1);
    for(int i = 1; i <= n; i++){
        cin >> w[i];
    }

    vector<pair<int,int>> edges(m+1);
    for(int i = 1; i <= m; i++){
        cin >> edges[i].first >> edges[i].second;
    }

    vector<Query> queries(q);
    vector<bool> dele(m+1, false);

    for(int i = 0; i < q; i++){
        char c;
        cin >> c;
        queries[i].t = c;
        if(c == 'D'){
            cin >> queries[i].a;
            dele[queries[i].a] = true;
        } else { 
            cin >> queries[i].a >> queries[i].b;
            queries[i].old = w[queries[i].a];
            w[queries[i].a] = queries[i].b;
        }
    }

    DSU dsu(n, w);

    for(int i = 1; i <= m; i++){
        if(!dele[i]){
            auto [u,v] = edges[i];
            dsu.unite(u,v);
        }
    }

    vector<long long> ans(q);
    for(int i = q-1; i >= 0; i--){

        ans[i] = dsu.max();

        if(queries[i].t == 'D'){

            auto [u,v] = edges[queries[i].a];
            dsu.unite(u, v);

        } else {

            int x = queries[i].a;
            int old_w = queries[i].old;
            int new_w = queries[i].b; 
            long long delta = (long long)old_w - (long long)new_w;

            dsu.deltapply(x, delta);

            w[x] = old_w;
        }
    }
    for(int i = 0; i < q; i++){
        cout << ans[i] << "\n";
    }
}